// ===== 第一题：宏任务与微任务交织 =====
console.log('1');

setTimeout(() => {
  console.log('2');
  Promise.resolve().then(() => console.log('3'));
}, 0);

Promise.resolve().then(() => {
  console.log('4');
  setTimeout(() => console.log('5'), 0);
});

console.log('6');
// 输出：1 → 6 → 4 → 2 → 3 → 5
// 推导：
// 宏任务1（script）: 同步 1, 6；注册 setTimeout#1 和 Promise#1
// 清空微任务: 4（执行 Promise#1，注册 setTimeout#2）
// 渲染（跳过）
// 宏任务2（setTimeout#1）: 同步 2；注册 Promise#2
// 清空微任务: 3
// 宏任务3（setTimeout#2）: 同步 5

// ===== 第二题：async/await 本质是微任务 =====
async function async1() {
  console.log('async1 start');
  await async2();
  // 下面这行等价于 async2().then(() => console.log('async1 end'))
  console.log('async1 end');
}
async function async2() {
  console.log('async2');
}

console.log('script start');
setTimeout(() => console.log('timeout'), 0);
async1();
new Promise(resolve => {
  console.log('promise1');
  resolve();
}).then(() => console.log('promise2'));
console.log('script end');
// 输出：script start → async1 start → async2 → promise1
//       → script end → async1 end → promise2 → timeout
// 关键：await async2() 执行后，console.log('async1 end') 被放入微任务队列
// 它在当前同步代码结束后、与 promise2 按注册顺序执行

// ===== 第三题：Node.js process.nextTick 优先级 =====
// 仅在 Node.js 中运行
console.log('start');
setTimeout(() => console.log('timeout'), 0);
Promise.resolve().then(() => console.log('promise'));
process.nextTick(() => console.log('nextTick'));
console.log('end');
// Node 输出：start → end → nextTick → promise → timeout
// process.nextTick 在当前操作结束后、Promise 微任务之前执行

